  constellations:{
    ursaMajor:{ name:'Katta Ayiq', text:'Katta Ayiq — osmonning eng mashhur turkumi. Yetti yorqin yulduzi «Katta Cho‘mich»ni hosil qiladi va qadimdan sayohatchilarga yo‘l ko‘rsatib kelgan. Cho‘michning ikki chetki yulduzi orqali Qutb yulduzini topish mumkin. Aslida bu yulduzlar bir-biridan o‘nlab yorug‘lik yili uzoqlikda joylashgan.' },
    ursaMinor:{ name:'Kichik Ayiq', text:'Kichik Ayiqning dumida Qutb yulduzi joylashgan. U doim shimolni ko‘rsatadi — ming yillar davomida dengizchilar va sayohatchilar unga qarab yo‘l topgan. Qutb yulduzi bizdan 433 yorug‘lik yili uzoqda va Quyoshdan 2 000 baravar yorqinroq porlaydi.' },
    orion:{ name:'Orion', text:'Orion — ovchi turkumi. Kamaridagi uch yulduz tep-tekis tizilgan, yaqinida esa yangi yulduzlar tug‘iladigan ulkan tumanlik bor. Yelkasidagi qizil Betelgeyze Quyoshdan 700 baravar katta — u istalgan payt o‘ta yangi yulduz sifatida portlashi mumkin.' },
    cassiopeia:{ name:'Kassiopeya', text:'Kassiopeya osmonda ulkan «W» harfini chizadi. Qadimgi afsonaga ko‘ra u mag‘rur malika bo‘lgan. 1572-yilda aynan shu turkumda mashhur o‘ta yangi yulduz portlashi kuzatilgan — u shunchalik yorqin ediki, kunduzi ham ko‘rinib turgan.' },
    cygnus:{ name:'Oqqush', text:'Oqqush turkumi Somon yo‘li bo‘ylab «uchib boradi». Eng yorqin yulduzi Deneb bizdan minglab yorug‘lik yili uzoqlikda — u ma’lum eng quvvatli yulduzlardan biri. Aynan shu turkumda birinchi tasdiqlangan qora tuynuk — Cygnus X-1 topilgan.' },
    scorpius:{ name:'Chayon', text:'Chayon — qadimgi afsonalarda Orionning dushmani; shuning uchun ular osmonda hech qachon birga ko‘rinmaydi. Yuragida qizil o‘ta gigant — Antares porlaydi. Uning nomi «Marsning raqibi» degan ma’noni beradi, chunki rangi qizilligi bilan Marsga o‘xshaydi.' }
  },
